using UnityEngine;

namespace Askich
{
    public static class CampaignData
    {
        public static readonly string[] Countries = { "Русь", "Франция", "Норвегия" };
        public static readonly string[] Classes = { "Дружинник", "Рыцарь", "Воин ярла" };
        public static readonly string[] Weapons = { "КОПЬЁ И КРУГЛЫЙ ЩИТ", "МЕЧ И РЫЦАРСКИЙ ЩИТ", "ТОПОР И КРУГЛЫЙ ЩИТ" };
        public static readonly string[] Traits = {
            "Длинное копьё держит врага на расстоянии.\n110 здоровья · дальность 2,2",
            "Крепкий щит бережёт выносливость.\n135 здоровья · усиленный блок",
            "Тяжёлый удар топором особенно опасен.\n105 здоровья · быстрый шаг" };
        public static readonly Color[] Colors = { new Color(.77f,.23f,.17f), new Color(.26f,.45f,.74f), new Color(.35f,.56f,.32f) };
        public static readonly string[] Speakers = { "Воевода Яромир", "Капитан Гийом", "Ярл Ингвар" };
        public static readonly string[] Introductions = {
            "Князья спорят о границе, а деревни остаются без защиты.\nТвоей дружине поручено провести обоз через Бережки\nи вернуть старую крепость над рекой.\n\nНо в письме воеводы есть странная приписка:\nпо ночам в пустой часовне снова звонит колокол.\n\nКому ты служишь — княжескому знамени или людям под ним?",
            "Крепость Сен-Рош держит дорогу между двумя владениями.\nЕё гарнизон исчез, и теперь пошли слухи о предательстве.\nТы дал клятву вернуть ворота под защиту короны.\n\nДеревня у дороги просит помощи, а приказ велит спешить.\nРядом замечен небольшой отряд тамплиеров.\n\nНе каждую клятву можно исполнить одним ударом меча.",
            "Зимний шторм оставил поселение без запасов.\nТы вернулся с дружиной ярла и нашёл дорогу перекрытой.\nНужно провести обоз и занять крепость у фьорда.\n\nСтарый союз распался: кто-то продал вашу дорогу наёмникам.\nИз заброшенной часовни доносится звон, хотя колокол снят.\n\nВерни людям дом — и узнай, кто наживается на страхе." };
        static readonly string[,] Missions = {
            { "Защитить Бережки", "Провести княжеский обоз", "Освободить пленных", "Удержать речные ворота", "Колокол под крепостью" },
            { "Защитить предместье", "Провести обоз Сен-Рош", "Освободить гарнизон", "Удержать королевские ворота", "Нарушенная клятва" },
            { "Вернуть поселение", "Доставить зимние запасы", "Освободить людей ярла", "Удержать ворота фьорда", "Последний звон" }
        };
        public static string Mission(int faction, int wave) => Missions[Mathf.Clamp(faction,0,2), Mathf.Clamp(wave-1,0,4)];
        public static string Objective(int wave) => wave == 2 ? "Сопроводи обоз: держись рядом с повозкой" : wave == 3 ? "Освободи 3 пленных клавишей E и разбей стражу" : wave == 4 ? "Защити ворота до конца нападения" : wave == 5 ? "Победи хранителя часовни и его людей" : "Очисти деревню от разбойников";
        public static string Brief(int faction, int completed, bool order)
        {
            string home = faction == 0 ? "Бережки" : faction == 1 ? "Сен-Рош" : "поселение у фьорда";
            if (completed == 0) return Introductions[faction];
            if (completed == 1) return "Деревня устояла. У разбойников найдено жалованье\nс печатью коменданта крепости. Это не случайный набег.\n\nТеперь нужно доставить припасы. Держись рядом с повозкой,\nчтобы возница решился ехать. Не дай нападающим её разбить.\n\n" + Speakers[faction] + ": «Сначала люди. Потом разберёмся с печатью».";
            if (completed == 2) return "Обоз добрался до крепости. За решётками сидят люди,\nкоторых комендант объявил предателями.\n\nСтарый лекарь говорит: хозяин часовни нашёл реликвию\nи с тех пор не снимает доспехов даже во сне.\n\nОсвободи пленных. Подойди к клетке и нажми E.\nИх показания стоят больше, чем приказ с любой печатью.";
            if (completed == 3) return "У ворот тебя встречает брат Матье из ордена тамплиеров.\nОн ищет пропавшую реликвию, а не службу чужому правителю.\n\n«Наши цели сегодня совпали. Приму твой бой как свой,\nесли позволишь помочь людям и вернуть реликвию в часовню».\n\nМожно принять союз: Матье будет сражаться рядом.\nИли сохранить независимость и опереться на свою дружину.";
            return order
                ? "Матье: «Комендант спрятался под часовней. Реликвия\nне дарует бессмертие — лишь не позволяет отпустить страх».\n\nЗа воротами тихо. " + home + " ждёт возвращения людей.\n\nОстался последний бой. Хранитель медленный, но его удар\nопасен. Следи за замахом и береги выносливость."
                : "Ты отказался от чужой присяги. Дружина стоит за тебя.\n\nПленные показали путь к часовне. Там скрывается хозяин\nразбойников — комендант, прикованный к старой реликвии.\n\nОстался последний бой. " + home + " ждёт твоего решения:\nсохранить реликвию как свидетельство или оставить её земле.";
        }
    }
}
